CREATE TABLE IF NOT EXISTS governed_matters(id BIGSERIAL PRIMARY KEY,tenant_id TEXT NOT NULL,matter_ref TEXT NOT NULL,jurisdiction TEXT NOT NULL,case_type TEXT NOT NULL,rule_version TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'intake',filing_receipt TEXT,decision JSONB,appeal_history JSONB NOT NULL DEFAULT '[]'::jsonb,idempotency_key TEXT NOT NULL,request_hash TEXT NOT NULL,created_by BIGINT NOT NULL,reviewed_by BIGINT,version INTEGER NOT NULL DEFAULT 1,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),UNIQUE(tenant_id,matter_ref),UNIQUE(tenant_id,idempotency_key),CHECK(status IN ('intake','evidence_ready','professional_review','authorized','filing_ready','filed','decision','appeal','closed')));
CREATE TABLE IF NOT EXISTS matter_evidence(id BIGSERIAL PRIMARY KEY,tenant_id TEXT NOT NULL,matter_id BIGINT NOT NULL REFERENCES governed_matters(id),document_type TEXT NOT NULL,storage_key TEXT NOT NULL,checksum TEXT NOT NULL,version TEXT NOT NULL,citations JSONB NOT NULL DEFAULT '[]'::jsonb,privilege_classification TEXT NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),UNIQUE(tenant_id,matter_id,checksum));
CREATE TABLE IF NOT EXISTS matter_deadlines(id BIGSERIAL PRIMARY KEY,tenant_id TEXT NOT NULL,matter_id BIGINT NOT NULL REFERENCES governed_matters(id),deadline_type TEXT NOT NULL,trigger_date DATE NOT NULL,due_at TIMESTAMPTZ NOT NULL,calendar_version TEXT NOT NULL,notification JSONB NOT NULL,status TEXT NOT NULL DEFAULT 'open',created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS matter_parties(id BIGSERIAL PRIMARY KEY,tenant_id TEXT NOT NULL,matter_id BIGINT NOT NULL REFERENCES governed_matters(id),party_ref TEXT NOT NULL,role TEXT NOT NULL,identity_vault_ref TEXT NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),UNIQUE(tenant_id,matter_id,party_ref));
CREATE TABLE IF NOT EXISTS matter_tasks(id BIGSERIAL PRIMARY KEY,tenant_id TEXT NOT NULL,matter_id BIGINT NOT NULL REFERENCES governed_matters(id),task_type TEXT NOT NULL,assigned_to BIGINT,status TEXT NOT NULL DEFAULT 'open',due_at TIMESTAMPTZ,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS matter_communications(id BIGSERIAL PRIMARY KEY,tenant_id TEXT NOT NULL,matter_id BIGINT NOT NULL REFERENCES governed_matters(id),channel TEXT NOT NULL,template_version TEXT NOT NULL,delivery_reference TEXT,status TEXT NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS matter_integration_runs(id BIGSERIAL PRIMARY KEY,tenant_id TEXT NOT NULL,provider TEXT NOT NULL,operation TEXT NOT NULL,status TEXT NOT NULL,external_reference TEXT,error_code TEXT,error_message TEXT,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),CHECK(status IN ('queued','succeeded','failed','manual_review')));
CREATE TABLE IF NOT EXISTS matter_audit_events(id BIGSERIAL PRIMARY KEY,tenant_id TEXT NOT NULL,actor_user_id BIGINT NOT NULL,action TEXT NOT NULL,entity_id TEXT NOT NULL,before_state JSONB,after_state JSONB,request_id TEXT NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
